const body = $input.item.json.body || $input.item.json;
const action  = body.action  || 'enhance_description';
const text    = (body.text   || '').trim();
const context = body.context || 'Professional consultant';
const locale  = body.locale  || 'fr';

const LANG_MAP = {
  en:'English', fr:'French', es:'Spanish', ar:'Arabic',
  pt:'Portuguese', de:'German', it:'Italian', nl:'Dutch', tr:'Turkish'
};
const language = LANG_MAP[locale] || 'French';

if (!text) throw new Error('MISSING_TEXT: text field is required and cannot be empty.');

// Each action has a system role and a precise instruction.
// All prompts in English — model outputs in the target language.
const ACTIONS = {

  enhance_description: {
    system: `You are a world-class B2B copywriter specializing in professional services.
Consultant domain: ${context}. Output language: ${language}.`,
    instruction: `Rewrite this description to make it more professional, compelling, and conversion-oriented.
Preserve the original meaning and key facts. Enrich the vocabulary. Add impact without being artificial.
Eliminate weak phrases ("I try to", "I hope", "I like to"). Use active voice and results-oriented language.
Return ONLY the improved text — no quotes, no introduction, no commentary.`
  },

  fix_spelling: {
    system: `You are an expert proofreader and language specialist. Output language: ${language}.`,
    instruction: `Correct ONLY spelling, grammar, punctuation, and accents in this text.
Do NOT change the meaning, style, tone, or sentence structure in any way.
Do NOT rephrase, expand, or improve — only fix errors.
Return ONLY the corrected text.`
  },

  make_professional: {
    system: `You are a senior LinkedIn personal branding expert for consultants and executives.
Context: ${context}. Output language: ${language}.`,
    instruction: `Rewrite this text to be ultra-professional, worthy of a senior consultant's LinkedIn profile.
Tone: confident, expert, results-oriented. Avoid all clichés ("passionate", "dynamic", "results-driven").
Lead with value delivered to clients, not personal qualities. Use concrete, specific language.
Return ONLY the rewritten text.`
  },

  generate_titles: {
    system: `You are an expert in copywriting and high-impact audit/service titles.
Context: ${context}. Output language: ${language}.`,
    instruction: `Generate exactly 3 compelling titles based on this text.
Each title must be: 4-8 words, benefit-focused for the prospect, specific to the consultant's domain.
Include an element of curiosity, urgency, or transformation in each title.
Return ONLY this exact format — nothing else:
Title 1: [title]
Title 2: [title]
Title 3: [title]`
  },

  generate_bio: {
    system: `You are an expert in professional bio writing for consultants.
Context: ${context}. Output language: ${language}.`,
    instruction: `Write a punchy professional bio (120-180 characters max) based on this information.
Use this formula: "I help [specific audience] achieve [specific outcome] through [method/expertise]."
Tone: direct, authentic, client-value-focused. No adjectives without proof.
Return ONLY the bio — no quotes, no explanation.`
  },

  generate_cta: {
    system: `You are an expert conversion copywriter specializing in call-to-action optimization.
Context: ${context}. Output language: ${language}.`,
    instruction: `Generate 3 high-converting CTA variants based on this text.
Each CTA: 4-8 words max, clear action verb, visible benefit, implicit urgency or exclusivity.
Vary the angle: one urgency-based, one benefit-based, one curiosity-based.
Return ONLY this exact format — nothing else:
CTA 1: [text]
CTA 2: [text]
CTA 3: [text]`
  },

  translate: {
    system: `You are a professional translator and language expert. Target language: ${language}.`,
    instruction: `Translate this text into ${language}, preserving the exact tone, style, nuances, and structure.
If the text is already in ${language}, lightly refine it for fluency and naturalness.
Return ONLY the translation — no notes, no explanation.`
  },

  summarize: {
    system: `You are an expert in professional content summarization. Output language: ${language}.`,
    instruction: `Summarize this text in 2-3 sharp, impactful sentences that capture the essential message.
Keep the most valuable and differentiating points. Remove all filler and redundancy.
The summary must stand alone — it should make sense without reading the original.
Return ONLY the summary.`
  }
};

const selected = ACTIONS[action] || ACTIONS['enhance_description'];

const fullPrompt =
`<s>
${selected.system}
</s>

<instruction>
${selected.instruction}
</instruction>

<original_text>
${text}
</original_text>`;

return {
  json: {
    prompt: fullPrompt,
    action,
    language
  }
};
